-- Only the named temporary registration by the known QA account, with no votes.
with target as materialized (select d.* from voting_private.day_registrations d join public.people p on p.id=d.person_id where p.full_name='QA REG HTTP 20261015 TEMP' and d.registered_by='a141e010-2026-4014-8000-000000000004' and not exists(select 1 from voting_private.participation v where v.identity_id=d.identity_id)), s as(delete from voting_private.sessions where identity_id in(select identity_id from target)), a as(delete from voting_private.attendance where identity_id in(select identity_id from target)), d as(delete from voting_private.day_registrations where id in(select id from target)), e as(delete from voting_private.eligibility where identity_id in(select identity_id from target)), ip as(delete from voting_private.identity_people where identity_id in(select identity_id from target)), i as(delete from voting_private.identities where id in(select identity_id from target)) delete from public.people where id in(select person_id from target) returning id;
